        section.content-section{padding:82px 0}.section-head{max-width:700px;margin-bottom:34px}.kicker{display:block;text-transform:uppercase;letter-spacing:.14em;color:#a56a0c;font-size:.74rem;font-weight:900;margin-bottom:10px}.section-head h2{font-size:clamp(2rem,3.8vw,3.05rem);line-height:1.12;letter-spacing:-.05em;color:var(--navy);margin:0 0 14px}.section-head p{margin:0;color:var(--muted);font-size:1rem;line-height:1.8}.section-head.center{text-align:center;margin-inline:auto}
